#!/usr/bin/env node
// Probe helper for the Python-Markdown 3.10.2 reference executable.
//
//   node /tmp/pm.mjs '<markdown text>'      -> runs text through all 3 modes
//   node /tmp/pm.mjs --file path.md         -> same, text read from a file
//
// In the inline form the two-char sequences \n \t \r \\ are unescaped.
// Use --file for anything with tricky quoting.
//
// Modes: a = markdown.markdown(x)                (core, no extensions)
//        b = markdown.markdown(x, extensions=['tables'])
//        c = markdown.markdown(x, extensions=['extra'])
//
// Each mode is run in its own process invocation with the other two args set
// to '' so the outputs can never collide with the document's own content.
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test11_executable';

function unesc(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '\\' && i + 1 < s.length) {
      const n = s[i + 1];
      if (n === 'n') { out += '\n'; i++; continue; }
      if (n === 't') { out += '\t'; i++; continue; }
      if (n === 'r') { out += '\r'; i++; continue; }
      if (n === '\\') { out += '\\'; i++; continue; }
    }
    out += s[i];
  }
  return out;
}

function run(args) {
  try {
    return { out: execFileSync(EXE, args, { encoding: 'utf8', maxBuffer: 1 << 28 }), rc: 0 };
  } catch (e) {
    return { out: (e.stdout || '') + (e.stderr || ''), rc: e.status, err: true };
  }
}

// print(a); print(b); print(c)  ->  a\nb\nc\n
// Isolating one arg lets us recover it byte-exactly by trimming the known
// number of empty lines the other two print statements contribute.
function mode(text, which) {
  const args = which === 'a' ? ['--a', text, '--b', '', '--c', '']
    : which === 'b' ? ['--a', '', '--b', text, '--c', '']
      : ['--a', '', '--b', '', '--c', text];
  const r = run(args);
  if (r.err) return { text: r.out, rc: r.rc };
  const lead = which === 'a' ? 0 : which === 'b' ? 1 : 2;   // empty lines before
  const trail = which === 'a' ? 3 : which === 'b' ? 2 : 1;  // "\n" x N after
  return { text: r.out.slice(lead, r.out.length - trail), rc: 0 };
}

let text;
if (process.argv[2] === '--file') {
  text = readFileSync(process.argv[3], 'utf8');
} else if (process.argv[2] !== undefined) {
  text = unesc(process.argv[2]);
} else {
  console.error('usage: node /tmp/pm.mjs <text>   |   node /tmp/pm.mjs --file <path>');
  process.exit(2);
}

const a = mode(text, 'a');
const b = mode(text, 'b');
const c = mode(text, 'c');

console.log('INPUT       ' + JSON.stringify(text));
console.log('--- core (no extensions) ---');
console.log(a.text);
console.log('CORE_JSON   ' + JSON.stringify(a.text));
console.log('--- tables ---');
console.log(b.text);
console.log('TABLES_JSON ' + JSON.stringify(b.text));
console.log('--- extra ---');
console.log(c.text);
console.log('EXTRA_JSON  ' + JSON.stringify(c.text));
console.log('RC ' + a.rc + ' ' + b.rc + ' ' + c.rc);

